{
  "name": "txpwr_limit_apply",
  "confidence": "medium",
  "docstring": "Apply a transmit-power limit mask from configuration, update the associated state flag, and send an HCI event when a limit/no-limit transition is observed.",
  "subsystem": "rf",
  "var_renames": {
    "result": "txpwr_cfg",
    "a2": "txpwr_ctx",
    "v4": "evt_buf"
  },
  "struct_hints": [
    {
      "offset": 27,
      "meaning": "uint8 index into a global tx-power limit mask table"
    },
    {
      "offset": 30,
      "meaning": "uint16 configuration/status field; bit 0x1000 enables limit processing"
    },
    {
      "offset": 310,
      "meaning": "uint8 tx-power or channel state byte tested against the limit mask"
    },
    {
      "offset": 53,
      "meaning": "uint8 state flags; bit 0x02 indicates no-limit state, bit 0x08 indicates limit state"
    },
    {
      "offset": 32,
      "meaning": "uint16 value copied into the first two bytes of the generated event buffer"
    },
    {
      "offset": 34,
      "meaning": "uint8 value copied into byte 3 of the generated event buffer"
    }
  ]
}
